<?php
declare(strict_types=1);
function csrf_token(): string {return $_SESSION['csrf']??=bin2hex(random_bytes(32));}
function csrf_field(): string {return '<input type="hidden" name="_token" value="'.e(csrf_token()).'">';}
function verify_csrf(): void { $v=$_POST['_token']??($_SERVER['HTTP_X_CSRF_TOKEN']??'');if(!is_string($v)||!hash_equals(csrf_token(),$v)){if(str_starts_with(route_path(),'/api/'))json_out(['error'=>'Your session expired. Reload the page.'],419);abort_page(419,'Your session expired. Reload the form.');} }
function current_user(): ?array {static $cached=false;if($cached!==false)return $cached;$id=$_SESSION['user_id']??0;if(!$id||!installed())return $cached=null;$u=row('SELECT * FROM users WHERE id=?',[$id]);if(!$u||$u['status']!=='active'||(int)$u['auth_version']!==(int)($_SESSION['auth_version']??0)){unset($_SESSION['user_id']);return $cached=null;}if(!empty($_SESSION['device_token'])){$device=row('SELECT * FROM device_sessions WHERE token_hash=? AND user_id=? AND revoked_at IS NULL',[hash('sha256',$_SESSION['device_token']),$id]);if(!$device){unset($_SESSION['user_id']);return $cached=null;}sql('UPDATE device_sessions SET last_seen=? WHERE id=?',[now(),$device['id']]);}else{unset($_SESSION['user_id']);return $cached=null;}if((int)($_SESSION['last_seen']??0)<time()-1800){unset($_SESSION['user_id']);flash('Please sign in again after 30 minutes of inactivity.','warning');return $cached=null;}$_SESSION['last_seen']=time();return $cached=$u;}
function require_user(array $roles=[]): array {$u=current_user();if(!$u){if(str_starts_with(route_path(),'/api/'))json_out(['error'=>'Please sign in.'],401);go('login');}if(setting('staff_mfa_required','0')==='1'&&$u['role']!=='citizen'&&!$u['totp_confirmed']&&!str_starts_with(route_path(),'/profile/security')&&route_path()!=='/logout')go('profile/security');if($roles&&!in_array($u['role'],$roles,true))abort_page(403,'You do not have access to this area.');return $u;}
function is_staff(?array $u=null): bool {$u=$u??current_user();return $u && (can('requests.scope_department',$u)||can('requests.scope_all',$u));}
function audit(string $action,?int $entity=null,array $data=[]): void {insert('audit_logs',['actor_id'=>$_SESSION['user_id']??null,'action'=>$action,'entity_id'=>$entity,'metadata'=>json_encode($data,JSON_UNESCAPED_UNICODE),'ip_address'=>substr($_SERVER['REMOTE_ADDR']??'CLI',0,64),'created_at'=>now()]);}
function rate_limit(string $key,int $limit,int $seconds): void {$name=ROOT.'/storage/cache/rate_'.hash('sha256',$key);$f=fopen($name,'c+');if(!$f)throw new RuntimeException('Rate limiter unavailable');flock($f,LOCK_EX);$v=json_decode(stream_get_contents($f)?:'[]',true);$v=array_values(array_filter(is_array($v)?$v:[],fn($t)=>(int)$t>time()-$seconds));if(count($v)>=$limit){flock($f,LOCK_UN);fclose($f);if(str_starts_with(route_path(),'/api/'))json_out(['error'=>'Too many requests. Please try again later.'],429);abort_page(429,'Too many attempts. Please try again later.');}$v[]=time();ftruncate($f,0);rewind($f);fwrite($f,json_encode($v));flock($f,LOCK_UN);fclose($f);}
function text_input(string $key,int $max,bool $required=true): string {$raw=$_POST[$key]??'';if(!is_scalar($raw))throw new InvalidArgumentException('Invalid '.label($key).'.');$v=trim((string)$raw);if(($required&&$v==='')||mb_strlen($v)>$max)throw new InvalidArgumentException(label($key).' is required and must be no longer than '.$max.' characters.');return $v;}
function email_input(string $key='email'): string {$v=strtolower(text_input($key,190));if(!filter_var($v,FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('Enter a valid email address.');return $v;}
function phone_input(string $key='phone',bool $required=true): string {$p=text_input($key,25,$required);if($p!==''&&!preg_match('/^\+?[0-9 ()-]{7,25}$/',$p))throw new InvalidArgumentException('Enter a valid phone number.');return $p;}
function password_valid(string $p): void {if(strlen($p)<12||strlen($p)>72||!preg_match('/[A-Za-z]/',$p)||!preg_match('/[0-9]/',$p))throw new InvalidArgumentException('Use a password of 12–72 bytes including letters and numbers.');}
function can_view(array $r,array $u): bool {if($r['status']==='draft'&&(int)$r['user_id']!==(int)$u['id'])return false;return can('requests.scope_all',$u)||(can('requests.scope_own',$u)&&(int)$r['user_id']===(int)$u['id'])||(can('requests.scope_department',$u)&&$u['department_id']&&(int)$r['department_id']===(int)$u['department_id']);}
function scoped_request(int $id,array $u): array {$r=row('SELECT r.*,s.title service_title,s.requirements,s.fee,d.name department_name,u.name citizen_name,u.email citizen_email,u.phone citizen_phone,a.name officer_name FROM requests r JOIN services s ON s.id=r.service_id JOIN departments d ON d.id=r.department_id JOIN users u ON u.id=r.user_id LEFT JOIN users a ON a.id=r.assigned_to WHERE r.id=?',[$id]);if(!$r||!can_view($r,$u))abort_page(404,'Request not found.');return $r;}
function request_scope(array $u,string $alias='r'): array {if(can('requests.scope_all',$u))return ['1=1',[]];if(can('requests.scope_department',$u))return [$alias.'.department_id=?',[(int)($u['department_id']??0)]];if(can('requests.scope_own',$u))return [$alias.'.user_id=?',[(int)$u['id']]];return ['1=0',[]];}
